module.exports = function stubReactCompilerInner(_api, options) {
  return {
    name: "stub-react-compiler-inner",
    visitor: {
      Program() {
        options?.logger?.logEvent("stub", {
          kind: "CompileSuccess",
          fnName: "stub-plugin-from-inner",
          fnLoc: { start: { line: 1, column: 0 }, end: { line: 1, column: 0 } },
        });
      },
    },
  };
};
